/// Verifies that a buffer of bytes contains a `SDI`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_sdi_unchecked`.
#[inline]
pub fn root_as_sdi(buf: &[u8]) -> Result<SDI<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<SDI>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `SDI` and returns it.
